const now = new Date();
const lastWeek = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
return [{
  json: {
    since: lastWeek.toISOString(),
    until: now.toISOString()
  }
}];

// Get all inputs
const commits = $input.all()[0]?.json || [];
const issues = $input.all()[1]?.json || [];
const prs = $input.all()[2]?.json || [];

// Filter merged PRs from last week
const sinceDate = new Date($json.since);
const mergedPRs = prs.filter(pr => {
  if (!pr.merged_at) return false;
  return new Date(pr.merged_at) >= sinceDate;
});

// Build summary data
const data = {
  repo: $env.GITHUB_REPO,
  owner: $env.GITHUB_OWNER,
  language: $env.LANGUAGE || 'EN',
  weekStart: $json.since,
  weekEnd: $json.until,
  commits: {
    count: commits.length,
    items: commits.slice(0, 10).map(c => ({
      message: c.commit?.message?.split('\n')[0],
      author: c.commit?.author?.name || c.author?.login
    }))
  },
  issues: {
    count: issues.length,
    items: issues.slice(0, 10).map(i => ({
      number: i.number,
      title: i.title
    }))
  },
  pullRequests: {
    count: mergedPRs.length,
    items: mergedPRs.slice(0, 10).map(p => ({
      number: p.number,
      title: p.title,
      author: p.user?.login
    }))
  }
};

return [{ json: data }];

